contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 newBetLimit, uint256 wagerAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (wagerAmount)); require(wagerAmount <= 1000000000000000000000000000000);
        require(wagerAmount == newBetLimit);
        require(address(this).balance >= wagerAmount);

        c.AdjustBetAmounts(newBetLimit); if (__ESBMC_reverted()) return;
        c.OpenToThePublic(); if (__ESBMC_reverted()) return;

        uint256 beforeBetLimit = c.currentBetLimit(); if (__ESBMC_reverted()) return;
        bool beforePlayerWagered = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;

        c.wager{value: wagerAmount}(); if (__ESBMC_reverted()) return;

        bool afterWagerRecorded = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;

        c.play(); if (__ESBMC_reverted()) return;

        bool afterPlayWagered = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;

        assert(beforeBetLimit == newBetLimit && !beforePlayerWagered && afterWagerRecorded && !afterPlayWagered);
    }

    receive() external payable {}
}

