        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        wagerAmount = newBetLimit;
        vm.assume(address(this).balance >= wagerAmount);
        try c.AdjustBetAmounts(newBetLimit) {} catch { return; }
        try c.OpenToThePublic() {} catch { return; }
        uint256 beforeBetLimit;
        try c.currentBetLimit() returns (uint256 __r) { beforeBetLimit = __r; } catch { return; }
